-- Isolated identities, transaction rolled back. Run after the monitoring schema.
begin;
select set_config('cante.mon_user',gen_random_uuid()::text,true),set_config('cante.mon_other',gen_random_uuid()::text,true),set_config('cante.mon_tenant',gen_random_uuid()::text,true),set_config('cante.mon_foreign',gen_random_uuid()::text,true);
insert into auth.users(id,email) select current_setting(k)::uuid,'monitor-fixture-'||current_setting(k)||'@example.invalid' from unnest(array['cante.mon_user','cante.mon_other']) k;
insert into public.customers(id,slug,name) select current_setting(k)::uuid,'monitor-fixture-'||current_setting(k),'SYNTHETIC daily-check test' from unnest(array['cante.mon_tenant','cante.mon_foreign']) k;
insert into public.customer_users(customer_id,user_id,role) values(current_setting('cante.mon_tenant')::uuid,current_setting('cante.mon_user')::uuid,'owner'),(current_setting('cante.mon_foreign')::uuid,current_setting('cante.mon_other')::uuid,'owner');
create function pg_temp.monitor_reject(command text) returns void language plpgsql security invoker as $$ begin begin execute command;exception when others then return;end;raise exception 'Expected rejection: %',command;end;$$;
select set_config('request.jwt.claim.sub',current_setting('cante.mon_user'),true);
set local role authenticated;
select public.set_tariff_daily_monitor(current_setting('cante.mon_tenant')::uuid,true);
select pg_temp.monitor_reject('select lease_token from public.tariff_daily_monitors');
select pg_temp.monitor_reject('select public.claim_tariff_daily_monitor()');
select pg_temp.monitor_reject($q$select public.set_tariff_daily_monitor(current_setting('cante.mon_foreign')::uuid,true)$q$);
select pg_temp.monitor_reject($q$insert into public.tariff_daily_events(customer_id) values(current_setting('cante.mon_tenant')::uuid)$q$);
reset role;
set local role service_role;
select set_config('cante.mon_lease',public.claim_tariff_daily_monitor()->>'lease_token',true);
do $$begin if nullif(current_setting('cante.mon_lease'),'') is null then raise exception 'Lease not claimed';end if;if public.claim_tariff_daily_monitor() is not null then raise exception 'Duplicate lease admitted';end if;end;$$;
select pg_temp.monitor_reject($q$select public.begin_tariff_daily_check(current_setting('cante.mon_tenant')::uuid,gen_random_uuid(),'SYNTHETIC','{}')$q$);
select set_config('cante.mon_check',public.begin_tariff_daily_check(current_setting('cante.mon_tenant')::uuid,current_setting('cante.mon_lease')::uuid,'SYNTHETIC CSV','{}')::text,true);
select pg_temp.monitor_reject($q$select public.finish_tariff_daily_monitor(current_setting('cante.mon_tenant')::uuid,current_setting('cante.mon_lease')::uuid,true)$q$);
select pg_temp.monitor_reject($q$select public.complete_tariff_daily_check(current_setting('cante.mon_check')::uuid,current_setting('cante.mon_foreign')::uuid,current_setting('cante.mon_lease')::uuid,'{}','[]')$q$);
select set_config('cante.mon_event',public.complete_tariff_daily_check(current_setting('cante.mon_check')::uuid,current_setting('cante.mon_tenant')::uuid,current_setting('cante.mon_lease')::uuid,'{"label":"SYNTHETIC"}','[]')::text,true);
select pg_temp.monitor_reject($q$select public.complete_tariff_daily_check(current_setting('cante.mon_check')::uuid,current_setting('cante.mon_tenant')::uuid,current_setting('cante.mon_lease')::uuid,'{}','[]')$q$);
insert into public.tariff_check_attestations(check_id,customer_id,terminal_event_id,input_sha256,event_sha256,verifier_version) select r.id,r.customer_id,e.id,r.input_sha256,e.payload_sha256,'SYNTHETIC-transaction-only' from public.tariff_check_records r join public.tariff_check_events e on e.check_id=r.id where r.id=current_setting('cante.mon_check')::uuid;
select public.finish_tariff_daily_monitor(current_setting('cante.mon_tenant')::uuid,current_setting('cante.mon_lease')::uuid,true);
do $$begin if not exists(select 1 from public.tariff_daily_monitors where customer_id=current_setting('cante.mon_tenant')::uuid and last_status='completed' and lease_token is null and last_success_at is not null and next_check_at>now()+interval '23 hours') then raise exception 'Successful daily check not retained';end if;end;$$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('cante.mon_other'),true);
set local role authenticated;
do $$begin if exists(select 1 from public.tariff_daily_monitors where customer_id=current_setting('cante.mon_tenant')::uuid) or exists(select 1 from public.tariff_check_records where id=current_setting('cante.mon_check')::uuid) then raise exception 'Cross-tenant daily check leak';end if;end;$$;
select pg_temp.monitor_reject($q$select public.complete_tariff_check(current_setting('cante.mon_check')::uuid,current_setting('cante.mon_tenant')::uuid,'{}','[]')$q$);
reset role;
select set_config('request.jwt.claim.sub',current_setting('cante.mon_user'),true);
set local role authenticated;
-- Existing manual writer remains functional and cannot rewrite its terminal.
insert into public.tariff_check_records(id,customer_id,filename,input_csv,engine,confirmations) values(gen_random_uuid(),current_setting('cante.mon_tenant')::uuid,'SYNTHETIC manual','manual','{}','{}');
select public.complete_tariff_check((select id from public.tariff_check_records where input_csv='manual' and customer_id=current_setting('cante.mon_tenant')::uuid),current_setting('cante.mon_tenant')::uuid,'{"manual":true}','[]');
select public.set_tariff_daily_monitor(current_setting('cante.mon_tenant')::uuid,false);
reset role;
rollback;
select 'PASS: daily leases, proof requirement, cross-tenant isolation, protected fields, immutable terminals, and existing manual writer; fixtures rolled back' as result;
